window.RV_BRAKE_LAWS = {"note":"The record behind tools/state-trailer-brake-laws.html. Every threshold here is the one the state's OWN vehicle code states, quoted as the code words it, and each row names the section it came from. The 3,000 pound figure people repeat is a federal exception written for commercial vehicles (49 CFR 393.42) and is not what binds a personal RV; what binds it is state equipment law, and the states do not agree. A state whose code has not been read has no entry here rather than a guess, because a threshold that is too high tells a reader to tow without brakes. scripts/test-state-brake-laws.js holds this file, assets/js/brakelaws.js and the page to the same facts.","verifiedOn":"2026-10-15","states":[{"code":"AZ","name":"Arizona","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semitrailer of that gross weight or more needs brakes that can be worked from the cab or that apply themselves with the tow vehicle's service brakes","section":"Arizona Revised Statutes 28-952","url":"https://www.azleg.gov/ars/28/00952.htm","quote":"When it is operated on a highway a trailer or semitrailer with a gross weight of three thousand pounds or more shall be equipped with brakes that are adequate to control the movement of and to stop and to hold the vehicle and that are designed to either be applied by the driver of the towing motor vehicle from its cab or be of a type that operates automatically when the service brakes of the towing motor vehicle are applied.","breakaway":"Required: the brakes must be designed and connected so that an accidental breakaway applies them automatically. No retention time is stated."},{"code":"CA","name":"California","threshold":"1,500 lb gross","shape":"requirement","appliesTo":"every trailer coach and camp trailer at or above that gross weight needs brakes on at least two wheels, adequate to let the combination meet the state's stopping distance","extra":"General trailers have their own lines: 6,000 lb for trailers operated at 20 mph or over, and 3,000 lb on at least two wheels from 1966 on.","section":"California Vehicle Code 26303, and 26302 for general trailers","url":"https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=VEH&sectionNum=26303","quote":null,"quoteNote":"The state's code site refuses automated reads, so the wording could not be quoted here. The section is named so it can be read directly.","breakaway":null},{"code":"CO","name":"Colorado","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semitrailer of that gross weight or more, with brakes on all wheels","extra":"A horse trailer of two horses or less is excepted, as are farm trailers that are not commercial vehicles.","section":"Colorado Revised Statutes 42-4-223","url":"https://leg.colorado.gov/sites/default/files/images/olls/crs2024-title-42.pdf","quote":"Every trailer or semitrailer of a gross weight of three thousand pounds or more, when operated upon a highway, shall be equipped with brakes adequate to control the movement of and to stop and to hold such vehicle and so designed as to be applied by the driver of the towing motor vehicle from the cab, and said brakes shall be so designed and connected that in case of an accidental breakaway of the towed vehicle the brakes shall be automatically applied.","breakaway":"Required: an accidental breakaway applies the brakes automatically. No retention time is stated."},{"code":"ID","name":"Idaho","threshold":"1,500 lb unladen","shape":"requirement","appliesTo":"a trailer or semitrailer of that UNLADEN weight or more, so the trigger is the trailer empty rather than loaded","section":"Idaho Code 49-933","url":"https://legislature.idaho.gov/statutesrules/idstat/title49/t49ch9/sect49-933/","quote":"Every trailer or semitrailer of an unladen weight of one thousand five hundred (1,500) pounds or more when operated upon a highway shall be equipped with brakes adequate to control the movement of and to stop and hold the vehicle and be designed to be applied by the driver of the towing motor vehicle from its cab.","breakaway":"Required: the brakes must be designed and connected so that an accidental breakaway applies them automatically. No retention time is stated."},{"code":"IL","name":"Illinois","threshold":"over 3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semitrailer over that gross weight, with brakes worked from the cab; between 3,000 and 5,001 lb needs brakes on only one wheel each side","section":"625 ILCS 5/12-301","url":"https://ilga.gov/legislation/ilcs/fulltext.asp?DocName=062500050K12-301","quote":"Except as provided in paragraph 4.1, every trailer or semitrailer of a gross weight of over 3,000 pounds, when operated upon a highway must be equipped with brakes adequate to control the movement of, to stop and to hold such vehicle, and designed so as to be operable by the driver of the towing vehicle from its cab.","breakaway":"Required above 5,000 lb: the brakes must be designed and connected so that an accidental breakaway applies them automatically. No retention time is stated."},{"code":"IN","name":"Indiana","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semitrailer of that gross weight or more, with brakes adequate to control, stop and hold it","section":"Indiana Code 9-19-3-3, with the exception restated in 9-19-3-4","url":"https://iga.in.gov/ic/2025/Title_9/Article_19.pdf","quote":"Subject to section 4 of this chapter, a trailer or semitrailer of a gross weight of at least three thousand (3,000) pounds, when operated upon a highway, must be equipped with brakes adequate to control the movement of and to stop and to hold the vehicle.","breakaway":"Required: the brakes must be designed and connected so that an accidental breakaway applies them automatically. No retention time is stated."},{"code":"IA","name":"Iowa","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer, semitrailer or travel trailer of that gross weight or more","extra":"The same section also asks for a separate means of applying the brakes from the cab, or self-actuating brakes, and a weight-equalizing hitch with sway control.","section":"Iowa Code 321.430","url":"https://www.legis.iowa.gov/docs/code/321.430.pdf","quote":"Every trailer, semitrailer, or travel trailer of a gross weight of three thousand pounds or more shall be equipped with brakes adequate to control the movement of and to stop and hold such vehicle when operated on the highways of this state.","breakaway":null},{"code":"KS","name":"Kansas","threshold":null,"shape":"performance","appliesTo":"no trailer weight threshold: the rule is a stopping standard, forty feet from 20 mph on a level dry hard surface, for every vehicle and combination","extra":"A trailer brake requirement appears only for the second towed vehicle in a multiple-trailer combination.","section":"K.S.A. 8-1734","url":"https://www.ksrevisor.gov/statutes/chapters/ch08/008_017_0034.html","quote":"Every motor vehicle and every combination of vehicles shall have a service braking system which will stop such vehicle or combination within forty (40) feet from an initial speed of twenty (20) miles per hour on a level, dry, smooth, hard surface.","breakaway":null},{"code":"MI","name":"Michigan","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer of less than 3,000 lb gross need not have brakes only if its weight stays within 40 percent of the towing vehicle's; at 15,001 lb gross, brakes are required on all wheels","section":"Michigan Vehicle Code 257.705","url":"https://www.legislature.mi.gov/Laws/MCL?objectName=MCL-257-705","quote":"A new motor vehicle, trailer, or semitrailer sold in this state and operated upon the highways shall be equipped with brakes on all wheels, except a motorcycle or moped, and except that a semitrailer, pole trailer, or trailer of less than 3,000 pounds gross weight need not be equipped with brakes if the gross weight of a trailer or pole trailer, no part of the load of which rests upon the towing vehicle, does not exceed 40% of the gross weight of the towing vehicle, and if the gross weight of the towing vehicle and the gross weight of a semitrailer or pole trailer, part of the load of which rests upon the towing vehicle, does not exceed 40% of the gross weight of the towing vehicle when connected to the semitrailer or pole trailer.","breakaway":null},{"code":"MN","name":"Minnesota","threshold":"3,000 lb gross, or heavier than the tow vehicle","shape":"requirement","appliesTo":"a trailer or semitrailer of that gross vehicle weight or more, OR one whose gross weight exceeds the empty weight of the towing vehicle, whichever comes first","section":"Minnesota Statutes 169.67","url":"https://www.revisor.mn.gov/statutes/cite/169.67","quote":"No trailer or semitrailer with a gross vehicle weight of 3,000 or more pounds, or a gross weight that exceeds the empty weight of the towing vehicle, may be drawn on a highway unless it is equipped with brakes that are adequate to control the movement of and to stop and hold the trailer or semitrailer.","breakaway":"Required above 3,000 lb: the brakes must be built so they stop and hold the trailer whenever it becomes detached from the towing vehicle. No retention time is stated."},{"code":"MO","name":"Missouri","threshold":null,"shape":"none","appliesTo":"no trailer weight threshold in the state's own code: the brake section requires motor vehicles to carry two sets of adequate brakes and says nothing about a trailer's weight","extra":"The 3,000 lb figure sometimes attributed to Missouri comes from the federal commercial rule, not from state law.","section":"RSMo 307.170","url":"https://revisor.mo.gov/main/OneSection.aspx?section=307.170","quote":"Brakes: All motor vehicles, except motorcycles, shall be provided at all times with two sets of adequate brakes, kept in good working order, and motorcycles shall be provided with one set of adequate brakes kept in good working order.","breakaway":null},{"code":"MT","name":"Montana","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 3,000 lb gross or less is excepted from all-wheel brakes only if its weight stays within 40 percent of the towing vehicle's and the combination meets the state's stopping standard","section":"Montana Code Annotated 61-9-304, breakaway in 61-9-305","url":"https://mca.legmt.gov/bills/MCA/title_0610/chapter_0090/part_0030/section_0040/0610-0090-0030-0040.html","quote":"trailers, semitrailers, pole trailers of a gross weight not exceeding 3,000 pounds, provided that: (a) the total weight on and including the wheels of the trailer or trailers may not exceed 40% of the gross weight of the towing vehicle when connected to the trailer or trailers; and (b) the combination of vehicles consisting of the towing vehicle and its total towed load is capable of complying with the performance requirements of 61-9-312;","breakaway":"Required above 3,000 lb on trailers built after January 1, 1966: applied automatically and promptly on breakaway, and remaining applied for at least 15 minutes."},{"code":"NE","name":"Nebraska","threshold":"3,000 lb gross loaded","shape":"requirement","appliesTo":"cabin trailers and recreational trailers at that gross loaded weight or more: brakes on at least two wheels from 3,000 lb, and on every wheel from 6,500 lb","extra":"The threshold names cabin and recreational trailers rather than every trailer; commercial trailers have their own rule.","section":"Nebraska Revised Statute 60-6,246","url":"https://nebraskalegislature.gov/laws/statutes.php?statute=60-6%2C246","quote":"Cabin trailers and recreational trailers having a gross loaded weight of three thousand pounds or more but less than six thousand five hundred pounds shall be equipped with brakes on at least two wheels, and such trailers with a gross loaded weight of six thousand five hundred pounds or more shall be equipped with brakes on each wheel.","breakaway":"Required: such trailers must carry a breakaway, surge or impulse switch so the trailer brakes activate if it comes off the tow vehicle."},{"code":"NV","name":"Nevada","threshold":"1,500 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer, house trailer or pole trailer of 3,000 lb gross or less is excepted, and below 1,500 lb gross no brakes are needed at all","extra":"Trailers built before July 1, 1975 also trigger on a ratio: 3,000 lb or more, or more than 40 percent of the towing vehicle.","section":"Nevada Revised Statutes 484D.250","url":"https://www.leg.state.nv.us/NRS/NRS-484D.html","quote":"Every trailer, semitrailer, house trailer and pole trailer equipped with air- or vacuum-actuated brakes and every trailer, semitrailer, house trailer and pole trailer with a gross weight in excess of 3,000 pounds, manufactured or assembled after July 1, 1969, must be equipped with brakes acting on all wheels and of such character as to be applied automatically and promptly, and remain applied for at least 15 minutes, upon breakaway from the towing vehicle.","breakaway":"Required above 3,000 lb on trailers built after July 1, 1969: applied automatically and promptly, and remaining applied for at least 15 minutes."},{"code":"NM","name":"New Mexico","threshold":"3,000 lb gross","shape":"exception","appliesTo":"trailers, semitrailers and pole trailers under 3,000 lb gross are excepted from all-wheel brakes; a house trailer over 3,000 lb needs brakes on at least two wheels","section":"NMSA 1978, 66-3-840","url":"https://www.nmonesource.com/nmos/nmsa/en/4422/1/document.do?iframe=true","quote":"trailers, semitrailers and pole trailers of a gross vehicle weight of less than three thousand pounds;","breakaway":null},{"code":"ND","name":"North Dakota","threshold":null,"shape":"speed","appliesTo":"no weight threshold: a trailer or semitrailer towed above 25 mph must have safety chains or brakes, so the trigger is speed rather than weight","section":"North Dakota Century Code 39-21-32","url":"https://ndlegis.gov/cencode/t39c21.pdf","quote":"Every trailer or semitrailer when operated upon a highway at a speed in excess of twenty-five miles [40.23 kilometers] per hour must be equipped with safety chains or brakes adequate to control the movement of and to stop and to hold such vehicle and so designed as to be applied by the driver of the towing motor vehicle from its cab, and said brakes must be so designed and connected that in case of an accidental breakaway of the towed vehicle the brakes are automatically applied.","breakaway":"Required where brakes are the chosen compliance: an accidental breakaway applies them automatically. No retention time is stated."},{"code":"OH","name":"Ohio","threshold":"2,000 lb empty","shape":"requirement","appliesTo":"a trailer or semitrailer of that EMPTY weight or more, built on or after January 1, 1942, so the trigger is the trailer empty rather than loaded","extra":"Travel trailers built on or after January 1, 2001 have their own 2,000 lb empty-weight line, and watercraft trailers a 3,000 lb gross line.","section":"Ohio Revised Code 4513.20","url":"https://codes.ohio.gov/ohio-revised-code/section-4513.20","quote":"Except as otherwise provided in this section, every trailer or semitrailer, except a pole trailer, with an empty weight of two thousand pounds or more, manufactured or assembled on or after January 1, 1942;","breakaway":"Required: the brakes must be designed and connected so that a breakaway applies them automatically. Ohio's code states no retention time; the 15 minutes often quoted for Ohio is the federal commercial figure."},{"code":"OR","name":"Oregon","threshold":null,"shape":"performance","appliesTo":"no trailer weight threshold at all: the rule is a stopping standard, 25 feet from 20 mph below 8,000 lb registration weight and 35 feet at or above it","extra":"Brakes are not required, but any safety equipment the trailer came with, brakes included, has to be kept in good working order.","section":"Oregon Revised Statutes chapter 815","url":"https://www.oregonlegislature.gov/bills_laws/ors/ors815.html","quote":"Vehicles with a registration weight of less than 8,000 pounds must be able to brake from a speed of 20 miles per hour to a stop within 25 feet.","breakaway":null},{"code":"SD","name":"South Dakota","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 3,000 lb gross or less is excepted from all-wheel brakes only if its weight stays within 40 percent of the towing vehicle's and the combination meets the state's stopping standard","extra":"A trailer built before July 1, 1974 is excepted up to 7,000 lb gross.","section":"SDCL 32-18-3, breakaway in 32-18-17","url":"https://sdlegislature.gov/api/Statutes/32-18-3.html","quote":"Trailers, semitrailers, or pole trailers of a maximum gross weight not exceeding three thousand pounds, and trailers, semitrailers, or pole trailers of a maximum gross weight not exceeding seven thousand pounds manufactured or assembled prior to July 1, 1974, need not be equipped with brakes acting on all wheels, provided that: (1) The total weight on and including the wheels of the trailer or trailers shall not exceed forty percent of the gross weight of the towing vehicle when connected to the trailer or trailers; and (2) The combination of vehicles, consisting of the towing vehicle and its total towed load, is capable of complying with the performance requirements of §§32-18-8 and 32-18-9.","breakaway":"Required above 3,000 lb on trailers built after July 1, 1967: applied automatically and promptly, and remaining applied for at least fifteen minutes."},{"code":"UT","name":"Utah","threshold":null,"shape":"performance","appliesTo":"no trailer weight threshold: the rule is a stopping standard, forty feet from 20 mph on a level dry hard surface, for a vehicle or combination","extra":"Utah adopts the federal braking standards by administrative rule, which is where a breakaway requirement would sit, and that rule could not be read from the state's site.","section":"Utah Code 41-6a-1623","url":"https://le.utah.gov/xcode/Title41/Chapter6A/41-6A-S1623.html","quote":"A motor vehicle and a combination of vehicles shall have a service braking system which will stop the motor vehicle or combination of vehicles within: (a) 40 feet from an initial speed of 20 miles per hour on a level, dry, smooth, hard surface; or (b) a shorter distance as may be specified by the department in accordance with federal standards.","breakaway":null},{"code":"WA","name":"Washington","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 3,000 lb gross or less is excepted from all-wheel brakes only if its weight stays within 40 percent of the towing vehicle's and the combination meets the state's stopping standard","extra":"Trailers built before July 1, 1965 are excepted up to 2,000 lb.","section":"RCW 46.37.340","url":"https://app.leg.wa.gov/RCW/default.aspx?cite=46.37.340","quote":"Trailers, cargo extensions, semitrailers, or pole trailers of a gross weight not exceeding three thousand pounds, provided that: (i) The total weight on and including the wheels of the trailer or trailers or cargo extension shall not exceed forty percent of the gross weight of the towing vehicle when connected to the trailer or trailers; and (ii) The combination of vehicles consisting of the towing vehicle and its total towed load, is capable of complying with the performance requirements of RCW 46.37.351;","breakaway":"Required above 3,000 lb on trailers built after January 1, 1964: brakes on all wheels, applied automatically on breakaway."},{"code":"WI","name":"Wisconsin","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer, semitrailer or other towed vehicle of that gross weight or more, built after January 1, 1942","extra":"A trailer may be towed without brakes if its gross weight is not more than 40 percent of the towing vehicle's and the combination meets the state's stopping standard.","section":"Wisconsin Statutes 347.35","url":"https://docs.legis.wisconsin.gov/statutes/statutes/347/iii/35","quote":"Except as provided in par. (am), no person shall operate on a highway any trailer, semitrailer or other towed vehicle having a gross weight of 3,000 pounds or more and manufactured after January 1, 1942 unless such vehicle is equipped with brakes adequate to control the movement of and to stop and hold it.","breakaway":null},{"code":"WY","name":"Wyoming","threshold":null,"shape":"performance","appliesTo":"no trailer weight threshold: the rule is a stopping standard, forty feet from 20 mph on a level dry hard surface, for every vehicle and combination","section":"Wyoming Statutes 31-5-950","url":"https://www.wyoleg.gov/Statutes/Compress/title31.pdf","quote":"Every motor vehicle and every combination of vehicles shall have a service braking system which will stop the vehicle or combination within forty (40) feet from an initial speed of twenty (20) miles per hour on a level, dry, smooth, hard surface or within such shorter distance as may be specified by the superintendent.","breakaway":null},{"code":"TX","name":"Texas","threshold":"4,500 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 4,500 lb gross or less need not have brakes; between 4,500 and 15,000 lb it still need not, if it is towed at no more than 30 mph","section":"Texas Transportation Code 547.401","url":"https://www.dps.texas.gov/section/commercial-vehicle-enforcement/brakes-required","quote":"A trailer, semitrailer, or pole trailer is not required to have brakes if: its gross weight is 4,500 pounds or less; or its gross weight is heavier than 4,500 pounds but not heavier than 15,000 pounds, and it is drawn at a speed of not more than 30 miles per hour.","sourceNote":"The state's code site serves its statutes through a JavaScript application and its PDF does not extract, so this is quoted from the Texas Department of Public Safety, which restates the same section.","breakaway":null},{"code":"FL","name":"Florida","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 3,000 lb gross or less is excepted from all-wheel brakes only if its weight stays within 40 percent of the towing vehicle's and the combination meets the state's stopping standard","extra":"Pole trailers over 3,000 lb built before January 1, 1972 are excepted as well.","section":"Florida Statutes 316.261","url":"https://www.flsenate.gov/Laws/Statutes/2025/316.261","quote":"Trailers, semitrailers, or pole trailers of a gross weight not exceeding 3,000 pounds, provided that: 1. The total weight on and including the wheels of the trailer or trailers shall not exceed 40 percent of the gross weight of the towing vehicle when connected to the trailer or trailers; and 2. The combination of vehicles, consisting of the towing vehicle and its total towed load, is capable of complying with the performance requirements of s. 316.262.","breakaway":"Required above 3,000 lb: applied automatically and promptly, and remaining applied for at least 15 minutes."},{"code":"GA","name":"Georgia","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer whose gross weight is over 3,000 lb, with service brakes on all wheels and a breakaway system","extra":"Farm trailers of 4,000 lb empty or less are excepted, and surge brakes are allowed on the ratios the state sets.","section":"O.C.G.A. 40-8-50","url":"https://dps.georgia.gov/frequently-asked-questions-mccd","quote":"Yes, if the gross weight of the trailer (weight of trailer and load) is over 3,000 lbs.","sourceNote":"Georgia's code viewer is a JavaScript application and its published code PDF omits the unamended brake sections, so this is quoted from the Georgia Department of Public Safety, which answers the same question.","breakaway":"Required: operative service brakes on all wheels, a parking brake system, an emergency brake system, and a breakaway braking system. No retention time is stated."},{"code":"NC","name":"North Carolina","threshold":"4,000 lb gross","shape":"requirement","appliesTo":"a semitrailer, trailer or separate vehicle attached by drawbar or coupling and having a gross weight of two tons needs brakes worked by the driver; a house trailer needs them at 1,000 lb gross","section":"N.C. Gen. Stat. 20-124","url":"https://www.ncleg.gov/EnactedLegislation/Statutes/PDF/BySection/Chapter_20/GS_20-124.pdf","quote":"Every semitrailer, or trailer, or separate vehicle, attached by a drawbar or coupling to a towing vehicle, and having a gross weight of two tons, and all house trailers of 1,000 pounds gross weight or more, shall be equipped with brakes controlled or operated by the driver of the towing vehicle, which shall conform to the specifications set forth in subsection (e) of this section and shall be of a type approved by the Commissioner.","breakaway":null},{"code":"SC","name":"South Carolina","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 3,000 lb gross or less is excepted from all-wheel brakes only if its weight stays within 40 percent of the towing vehicle's and the combination meets the state's stopping standard","section":"S.C. Code 56-5-4850","url":"https://www.scstatehouse.gov/code/t56c005.php","quote":"Trailers, semitrailers or pole trailers, of a gross weight not exceeding three thousand pounds, provided that: (a) The total weight on and including the wheels of the trailer shall not exceed forty per cent of the gross weight of the towing vehicle when connected to the trailer, and (b) The combination of vehicles, consisting of the towing vehicle and its total towed load, is capable of complying with the performance requirements of Section 56-5-4860.","breakaway":"Required above 3,000 lb: applied automatically and promptly, and remaining applied for at least fifteen minutes."},{"code":"VA","name":"Virginia","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a semitrailer, trailer or separate vehicle attached by drawbar, chain or coupling and having an actual gross weight of 3,000 lb or more, with brakes worked by the driver","extra":"Farm trailers hauling raw agricultural produce are excepted, as are vehicles towed for repair or repossession.","section":"Va. Code 46.2-1070","url":"https://law.lis.virginia.gov/vacodefull/title46.2/chapter10/article9/","quote":"Every semitrailer, trailer, or separate vehicle attached by a drawbar, chain, or coupling to a towing vehicle other than a farm tractor or a vehicle not required to obtain a registration certificate and having an actual gross weight of 3,000 pounds or more, shall be equipped with brakes controlled or operated by the driver of the towing vehicle, which shall conform to the specifications set forth in § 46.2-1067 and shall be of a type approved by the Superintendent.","breakaway":"Required above 3,000 lb on trailers built after January 1, 1964, by the state's safety-inspection regulation rather than the code section: applied automatically on breakaway and remaining fully applied for at least 15 minutes."},{"code":"TN","name":"Tennessee","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer of 3,000 lb gross or more needs brakes on all wheels; between 1,500 and 3,000 lb it needs brakes on one axle; under 1,500 lb it needs none","section":"Tenn. Code Ann. 55-9-204","url":"https://www.tn.gov/safety/tnhp/cvemain/trailer-inspection-requirements.html","quote":"Trailers with a gross weight of 3,000 lbs. or more are required to have brakes on ALL WHEELS. Trailers with a gross weight of 1,500 to 3,000 lbs. are required to have brakes on ONE axle. Trailers with a gross weight of less than 1,500 lbs. need NOT be equipped with brakes.","sourceNote":"Tennessee's code host sits behind an anti-bot wall, so this is quoted from the Tennessee Department of Safety and Homeland Security, which restates the same section.","breakaway":"Required: a trailer equipped with brakes must have an emergency breakaway braking device."},{"code":"AL","name":"Alabama","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 3,000 lb gross or less is excepted from all-wheel brakes only if its weight stays within 40 percent of the towing vehicle's and the combination meets the state's stopping standard","extra":"The statute itself sets no weight; it delegates to the Department of Public Safety's rules, and this is that rule.","section":"Ala. Admin. Code r. 760-X-1-.09","url":"https://admincode.legislature.state.al.us/administrative-code/760-X-1-.09","quote":"Trailers, Semi-Trailers, or Pole Trailers of a gross weight not exceeding 3,000 pounds, provided that: (i) The total weight on and including the wheels of the trailer or trailers shall not exceed 40 percent of the gross weight of the towing vehicle when connected to the trailer or trailers, and (ii) The combination of vehicles, consisting of the towing vehicle and its total towed load, is capable of complying with the performance requirements of this rule.","breakaway":"Required above 3,000 lb: applied automatically and promptly, and remaining applied for at least fifteen minutes."},{"code":"LA","name":"Louisiana","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semitrailer of 3,000 lb gross or more, with brakes worked from the cab","extra":"Between 3,000 and 5,000 lb gross, brakes on a single axle are enough.","section":"La. R.S. 32:341","url":"https://www.legis.la.gov/legis/Law.aspx?d=88276","quote":"Every trailer or semi-trailer of a gross weight of 3,000 pounds or more, when operated upon a highway of this state, shall be equipped with brakes adequate to control the movement of and to stop and hold such vehicle and so designed as to be applied by the driver of the towing motor vehicle from its cab, and said brakes shall be so designed and connected that in case of an accidental breakaway of the towed vehicle the brakes shall be automatically applied.","breakaway":"Required: an accidental breakaway applies the brakes automatically. No retention time is stated."},{"code":"CT","name":"Connecticut","threshold":"3,000 lb GVWR","shape":"requirement","appliesTo":"a trailer or semitrailer with a gross vehicle weight rating of 3,000 lb or more, with a braking system on all wheels","extra":"Brakes on trailers rated 8,000 lb or less need not be controllable from the driver's seat, which is what lets a surge-brake trailer comply.","section":"Connecticut General Statutes 14-81","url":"https://www.cga.ct.gov/current/pub/chap_246.htm","quote":"Each trailer or semitrailer having a gross vehicle weight rating of three thousand pounds or more shall, when operated on any public highway, be equipped with a braking system operating on all wheels.","breakaway":null},{"code":"RI","name":"Rhode Island","threshold":"4,000 lb gross","shape":"requirement","appliesTo":"every trailer or semi-trailer of that gross weight or more, with brakes worked from the driver's position","section":"R.I. Gen. Laws 31-23-4","url":"https://webserver.rilegislature.gov/Statutes/TITLE31/31-23/31-23-4.htm","quote":"Every trailer or semi-trailer of a gross weight of four thousand pounds (4,000 lbs.) or more, when operated upon a highway, shall be equipped with brakes adequate to control the movement of and to stop and to hold the vehicle, and so designed as to be applied by the driver of the towing motor vehicle from the driver's normal operating position, and the brakes shall be so designed and connected that in case of an accidental breakaway of the towed vehicle, the brakes shall be automatically applied.","breakaway":"Required: an accidental breakaway applies the brakes automatically. No retention time is stated."},{"code":"NH","name":"New Hampshire","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer or semi-trailer under 3,000 lb gross is excepted only if the towed axle weight stays within 40 percent of the sum of the towing vehicle's rated axle weights","extra":"A house trailer over 1,500 lb must be equipped as well.","section":"New Hampshire RSA 266:30","url":"https://gc.nh.gov/rsa/html/XXI/266/266-30.htm","quote":"This section shall not apply to: (a) A motor vehicle trailer or semi-trailer with a gross weight of less than 3,000 pounds if the axle weight of the towed vehicle does not exceed 40 percent of the sum of the rated axle weights of the towing vehicle.","breakaway":null},{"code":"VT","name":"Vermont","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semi-trailer, trailer coach or pole trailer of 3,000 lb gross or less need not have brakes only if its wheel weight stays within 40 percent of the towing vehicle's gross weight","extra":"Above that it is tiered: over 3,000 and under 6,000 lb needs brakes on at least one axle, and 6,000 lb or more needs them on all wheels.","section":"23 V.S.A. 1307","url":"https://legislature.vermont.gov/statutes/section/23/013/01307","quote":"Trailers, semi-trailers, trailer coaches, or pole trailers of a gross weight not exceeding 3,000 pounds need not have brakes, provided the total weight on, and including, the wheels of the trailer, semi-trailer, or pole trailer shall not exceed 40 percent of the gross weight of the towing vehicle when connected to the trailer, semi-trailer, or pole trailer.","breakaway":"Required above 3,000 lb: on breakaway the brakes are applied automatically and remain applied for not less than 15 minutes."},{"code":"ME","name":"Maine","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer or semitrailer of 3,000 lb gross or less is excepted from the all-wheel brake requirement","section":"29-A M.R.S. 1902","url":"https://legislature.maine.gov/statutes/29-A/title29-Asec1902.html","quote":"Special mobile equipment or a truck, truck tractor, tiny home, trailer or semitrailer must be equipped with adequate brakes acting on all wheels of all axles, except that the following need not meet this requirement: A. A trailer or semitrailer not exceeding a gross weight of 3,000 pounds;","breakaway":null},{"code":"MA","name":"Massachusetts","threshold":"10,000 lb unladen","shape":"requirement","appliesTo":"a trailer or semi-trailer with an UNLADEN weight over 10,000 lb, which must have air or electric brakes","extra":"Massachusetts sets no lower weight threshold for ordinary trailers; below that the state requires a safety chain rather than brakes.","section":"Massachusetts General Laws chapter 90, section 7","url":"https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXIV/Chapter90/Section7","quote":"Every trailer or semi-trailer having an unladen weight of more than ten thousand pounds shall be equipped with air or electric brakes.","breakaway":null},{"code":"NY","name":"New York","threshold":"1,000 lb unladen, or 3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semi-trailer weighing more than 1,000 lb UNLADEN, and any built on or after January 1, 1971 whose gross weight is over 3,000 lb, so a light trailer trips it empty","section":"N.Y. Vehicle & Traffic Law 375","url":"https://www.nysenate.gov/legislation/laws/VAT/375","quote":"Every trailer and semi-trailer weighing more than one thousand pounds unladen and every trailer and semi-trailer manufactured or assembled on or after January first, nineteen hundred seventy-one having a registered maximum gross weight, an actual gross weight or gross weight consisting of the unladen weight and maximum carrying capacity recommended by the manufacturer in excess of three thousand pounds also shall be equipped with adequate brakes in good working order if operated or drawn on the public highways of this state.","breakaway":"Not in the code section. The state's DMV requires a breakaway system on commercially used trailers, holding the trailer stationary for at least 15 minutes."},{"code":"NJ","name":"New Jersey","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer or semitrailer of 3,000 lb gross or less is excepted from brakes on all wheels only if its gross weight stays within 40 percent of the towing vehicle's","section":"N.J.S.A. 39:3-67","url":"https://pub.njleg.gov/statutes/STATUTES-TEXT.zip","quote":"Every motor vehicle, except a motor cycle, manufactured on or after July 1, 1938 when used on a highway shall be equipped with brakes on all wheels, except the front wheels of a 3-axle truck tractor and except any trailer or semitrailer of a gross weight not exceeding 3,000 pounds; provided, however, that the gross weight of any such trailer without brakes shall not exceed 40% of the gross weight of the towing vehicle, and that the gross weight of any such semitrailer without brakes shall not exceed 40% of the gross weight of the towing vehicle when the vehicles are connected.","sourceNote":"New Jersey's statute viewer is a JavaScript application that serves no text, so this is quoted from the Legislature's own published statutes archive.","breakaway":"Required on any trailer that must have brakes: applied automatically on breakaway, with means provided to stop and hold it for an adequate period. No fixed time is stated."},{"code":"PA","name":"Pennsylvania","threshold":null,"shape":"none","appliesTo":"no weight threshold in the statute: every vehicle and combination must have a service brake system adequate to stop and hold it, whatever it weighs","extra":"The 3,000 lb figure appears twice, and neither is a brake requirement: it is the weight above which a breakaway system is required, and a trailer of 3,000 lb or less is excepted from brakes on all wheels by the state's inspection regulation, only if it stays within 40 percent of the towing vehicle's weight.","section":"75 Pa.C.S. 4502, and 67 Pa. Code 175.123","url":"https://www.legis.state.pa.us/WU01/LI/LI/CT/HTM/75/00.045.002.000..HTM","quote":"Every vehicle and combination operated on a highway shall be equipped with a service brake system adequate to control the movement of and to stop and hold the vehicle or combination on any grade on which it is operated, under all conditions of loading, and adequate to meet the braking performance standards established by regulation of the department.","breakaway":"Required where the towed vehicle has brakes or exceeds 3,000 lb gross: it must be stopped and held automatically on breakaway. No retention time is stated."},{"code":"MD","name":"Maryland","threshold":"3,000 lb registered gross","shape":"exception","appliesTo":"a trailer, semitrailer or pole trailer of 3,000 lb registered gross or less is excepted from brakes on all wheels only if its wheel weight stays within 40 percent of the towing vehicle's and the combination meets the state's stopping standard","extra":"Between 3,000 and 10,000 lb, brakes are required on all wheels of at least one axle.","section":"Md. Code, Transportation 22-301","url":"https://mgaleg.maryland.gov/mgawebsite/laws/StatuteText?article=gtr&section=22-301","quote":"Every vehicle shall be equipped with brakes acting on all wheels, except: (1) Trailers, semitrailers, or pole trailers of a registered gross weight not exceeding 3,000 pounds, provided that: (i) The total weight on and including the wheels of the trailer or trailers does not exceed 40 percent of the gross weight of the towing vehicle when connected to the trailer or trailers; and (ii) The combination of vehicles, consisting of the towing vehicle and its total towed load, is capable of complying with the performance requirements of § 22-302 of this subtitle;","breakaway":"Required above 10,000 lb registered gross on trailers built after June 1, 1970, and on the 3,000 to 10,000 lb class: applied automatically and promptly, and remaining applied for at least 15 minutes."},{"code":"DE","name":"Delaware","threshold":"4,000 lb gross","shape":"speed","appliesTo":"a trailer or semitrailer over 4,000 lb gross may not be towed faster than 10 mph unless it has brakes the driver controls, so the rule is written as a speed limit rather than a brake requirement","section":"21 Del. C. 4305","url":"https://delcode.delaware.gov/title21/c043/sc01/index.html","quote":"No trailer or semitrailer with a gross weight of load and vehicle in excess of 4,000 pounds shall be operated on the highways of this State at a speed in excess of 10 miles per hour unless equipped with suitable brakes controlled by the operator of the towing vehicle.","breakaway":null},{"code":"DC","name":"District of Columbia","threshold":"3,000 lb gross","shape":"exception","appliesTo":"a trailer, semi-trailer or pole-trailer of 3,000 lb gross or less is excepted from brakes on all wheels only if its wheel weight stays within 40 percent of the towing vehicle's and the combination meets the district's stopping standard","section":"18 DCMR 720.9, breakaway in 18 DCMR 721.1","url":"https://dcregs.dc.gov/Common/DCMR/RuleList.aspx?DownloadFile=802C555F-0000-C1B8-AE5E-3EB62E81CB68","quote":"Each vehicle shall be equipped with brakes acting on all wheels except the following vehicles: (a) Trailers, semi-trailers, or pole-trailers of a gross weight not exceeding three thousand pounds (3,000 lbs.); Provided, that the following requirements are met: (1) The total weight on and including the wheels of the trailer or trailers shall not exceed forty per cent (40%) of the gross weight of the towing vehicle when connected to the trailer or trailers; and (2) The combination of vehicles, consisting of the towing vehicle and its total towed load, is capable of complying with the requirements of 724;","breakaway":"Required above 3,000 lb gross on trailers built after September 15, 1963: applied automatically and promptly, and remaining applied for at least fifteen minutes.","breakawayUrl":"https://dcregs.dc.gov/Common/DCMR/RuleList.aspx?DownloadFile=902C555F-0000-C724-B7AE-6971BEFBCE7B","sourceNote":"The District's section pages render through a JavaScript application that serves no text, so the two links on this row download the rule documents themselves: the first carries 720.9, the threshold this row quotes, and the second carries 721.1, the breakaway clause."},{"code":"AK","name":"Alaska","threshold":"5,000 lb GVWR","shape":"requirement","appliesTo":"towing a vehicle with a GVWR over 5,000 lb: the towed vehicle needs brakes on at least two wheels each side of a three-axle vehicle, or one wheel each side of a double or single axle","extra":"The same regulation also sets a stopping standard for every vehicle and combination: 40 feet from 20 mph, or 25 feet for a passenger car or single-unit vehicle rated 10,000 lb or less.","section":"13 AAC 04.205","url":"https://regs.akleg.gov/api/AAC/LookupIdRange?startID=7831660&endId=7831673","quote":"No driver may operate a motor vehicle on a public roadway or other vehicular way, towing a vehicle with a GVWR greater than 5,000 pounds, unless the following conditions are met: (1) the towed vehicle must have operating brakes on at least two wheels on each side of a three axle vehicle, or one wheel on each side of a double or single axle vehicle; (2) the towed vehicle requiring brakes must be equipped with an operating, breakaway system capable of applying all required brakes in the event of separation from the towing vehicle; and (3) the towing vehicle must be of sufficient size and weight to safely control the towed vehicle.","sourceNote":"Alaska's regulation viewer is a JavaScript application, so this is quoted from the Legislature's own regulation service, which is the text behind that viewer.","breakaway":"Required on a towed vehicle that needs brakes: an operating breakaway system capable of applying all required brakes on separation. No retention time is stated."},{"code":"HI","name":"Hawaii","threshold":"3,000 lb gross","shape":"inspection","appliesTo":"a trailer over 3,000 lb gross must fail its periodic inspection if it has no brakes worked from the tow vehicle, so the threshold sits in the inspection standard rather than in an equipment mandate","extra":"The same chapter sets a separate list for trailers of 3,000 lb or less, which does not include brakes.","section":"Hawaii Administrative Rules 19-133.2-40","url":"https://hidot.hawaii.gov/administration/files/2025/07/HAR_19_133_2_Periodic_Inspection_of_Vehicles_remediated.pdf","quote":"Trailers with a gross weight greater than 3, 000 pounds must fail inspection if they do not have the following: ... (8) Brakes that are actuated from the tow vehicle, and in the event of a breakaway, the brakes must self-actuate;","breakaway":"Required above 3,000 lb gross: on breakaway the brakes must self-actuate. No retention time is stated."},{"code":"KY","name":"Kentucky","threshold":null,"shape":"performance","appliesTo":"no trailer weight threshold: the rule is a stopping standard, 40 feet from 20 mph on dry asphalt or concrete, for any motor vehicle or combination","extra":"The only weight figure in the section is 10,000 lb GVW, which routes commercial vehicles to the federal standard rather than setting a trailer threshold.","section":"Kentucky Revised Statutes 189.090","url":"https://apps.legislature.ky.gov/law/statutes/statute.aspx?id=6306","quote":"Except for commercial motor vehicles with a declared gross vehicle weight of more the ten thousand (10,000) pounds, the service brakes upon any motor vehicle or combination of vehicles shall be adequate to stop the vehicle when traveling twenty (20) miles per hour within a distance of forty (40) feet when upon dry asphalt or concrete pavement surface free from loose material where the grade does not exceed one percent (1%).","breakaway":null},{"code":"WV","name":"West Virginia","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semitrailer of 3,000 lb gross or more, with brakes worked from the cab","extra":"A semitrailer of less than 1,500 lb gross need not have brakes.","section":"W. Va. Code 17C-15-31","url":"https://code.wvlegislature.gov/17C-15-31/","quote":"Every trailer or semitrailer of a gross weight of three thousand pounds or more when operated upon a highway shall be equipped with brakes adequate to control the movement of and to stop and to hold such vehicle and so designed as to be applied by the driver of the towing motor vehicle from its cab, and said brakes shall be so designed and connected that in case of an accidental breakaway of the towed vehicle the brakes shall be automatically applied.","breakaway":"Required: an accidental breakaway applies the brakes automatically. No retention time is stated."},{"code":"OK","name":"Oklahoma","threshold":"3,000 lb GVWR","shape":"requirement","appliesTo":"a trailer, semitrailer or pole trailer rated 3,000 lb GVWR or more; below that, brakes are still required if the towed weight exceeds 40 percent of the towing vehicle's GVWR","extra":"Surge brakes are expressly allowed on trailers hauling a vessel.","section":"47 O.S. 12-301","url":"https://www.oklegislature.gov/OK_Statutes/CompleteTitles/os47.pdf","quote":"Every trailer, semitrailer, and pole trailer of a gross vehicle weight rating of three thousand (3,000) pounds or more when operated upon a highway shall be equipped with brakes:","breakaway":"Required: applied automatically on breakaway, and means must be provided to maintain application for at least fifteen minutes."},{"code":"AR","name":"Arkansas","threshold":"3,000 lb gross","shape":"requirement","appliesTo":"a trailer or semitrailer of 3,000 lb gross or more, with brakes worked from the cab","extra":"A semitrailer of less than 1,500 lb gross need not have brakes.","section":"Ark. Code Ann. 27-37-501","url":"https://ardot.gov/wp-content/uploads/Arkansas-Motor-Vehicle-2025-508-compliant.pdf","quote":"Every trailer or semitrailer of a gross weight of three thousand pounds (3,000 lbs.) or more when operated upon a highway shall be equipped with brakes adequate to control the movement of, and to stop and to hold, the vehicle and so designed as to be applied by the driver of the towing motor vehicle from its cab.","sourceNote":"Quoted from the Arkansas Department of Transportation's own published compilation of the motor vehicle and traffic laws.","breakaway":"Required: the brakes must be designed and connected so that an accidental breakaway applies them automatically. No retention time is stated."}],"allStates":[["AL","Alabama"],["AK","Alaska"],["AZ","Arizona"],["AR","Arkansas"],["CA","California"],["CO","Colorado"],["CT","Connecticut"],["DE","Delaware"],["DC","District of Columbia"],["FL","Florida"],["GA","Georgia"],["HI","Hawaii"],["ID","Idaho"],["IL","Illinois"],["IN","Indiana"],["IA","Iowa"],["KS","Kansas"],["KY","Kentucky"],["LA","Louisiana"],["ME","Maine"],["MD","Maryland"],["MA","Massachusetts"],["MI","Michigan"],["MN","Minnesota"],["MS","Mississippi"],["MO","Missouri"],["MT","Montana"],["NE","Nebraska"],["NV","Nevada"],["NH","New Hampshire"],["NJ","New Jersey"],["NM","New Mexico"],["NY","New York"],["NC","North Carolina"],["ND","North Dakota"],["OH","Ohio"],["OK","Oklahoma"],["OR","Oregon"],["PA","Pennsylvania"],["RI","Rhode Island"],["SC","South Carolina"],["SD","South Dakota"],["TN","Tennessee"],["TX","Texas"],["UT","Utah"],["VT","Vermont"],["VA","Virginia"],["WA","Washington"],["WV","West Virginia"],["WI","Wisconsin"],["WY","Wyoming"]],"coverage":{"covered":50,"total":51,"missing":["MS"]}};
